// Author: MiYu. Script damage applies source attack/armor factors, illusion multipliers and real damage/death events.
#include "session.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <sstream>

namespace war3 {
namespace {float number(jass::Real v){return std::bit_cast<float>(v.bits());}jass::Real real(float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));}}
bool ScriptSession::damageUnit(std::uint32_t source,std::uint32_t target,float amount,unsigned attackType,unsigned damageType,bool attack,bool ranged,float* dealt) {
    if(dealt)*dealt=0;if(!std::isfinite(amount) || amount<0 || amount>1000000000)throw std::runtime_error("Damage amount outside supported range");if(attackType>6 || (damageType!=0 && damageType!=4 && damageType!=5 && (damageType<8 || damageType>26)))throw std::runtime_error("Unknown damage classification");if(!alive(source,NativeKind::Unit) || !alive(target,NativeKind::Unit))return false;auto from=units_.at(source),to=units_.at(target);if(from->removing || to->removing || to->invulnerable || capability(*to,"Avul") || number(to->life)<=0)return false;if(capability(*to,"Amim") && damageType!=26 && (attackType==4 || (damageType>=8 && damageType<=20) || damageType==23 || damageType==25))return false;double damage=double(amount)*from->damageDealt*to->damageTaken;
    if(damageType!=26){auto& data=definitions();auto defense=data.field(to->type,"UnitBalance","defType","normal");constexpr const char* armorTypes[]={"small","medium","large","fort","normal","hero","divine","none"};unsigned armor=8;for(unsigned i=0;i<8;++i)if(defense==armorTypes[i])armor=i;if(armor==8)throw std::runtime_error("Unknown source defense type: "+defense);constexpr const char* attacks[]={"Spells","Normal","Pierce","Siege","Magic","Chaos","Hero"};auto key=std::string("DamageBonus")+attacks[attackType];std::stringstream sourceTable(gameplay().value("Misc",key));std::string part;std::vector<float> factors;while(std::getline(sourceTable,part,',')){auto factor=std::stof(part);if(!std::isfinite(factor) || factor<0)throw std::runtime_error("Invalid source attack factor");factors.push_back(factor);}if(factors.size()!=8)throw std::runtime_error("Missing source attack/defense factors: "+key);damage*=factors[armor];if(damageType==4){float defensePoints=data.number(to->type,"UnitBalance","def")+to->technology.armor;if(to->hero)defensePoints+=to->appliedHeroStats[1]*gameplayNumber("AgiDefenseBonus",.3f)+gameplayNumber("AgiDefenseBase",-2);defensePoints=defensePoints*(1+to->aura.armorPercent)+to->aura.armor;double coefficient=gameplayNumber("DefenseArmor",.06f);if(coefficient<=0 || coefficient>=1)throw std::runtime_error("Unsupported armor coefficient");damage*=defensePoints>=0?1/(1+coefficient*defensePoints):2-std::pow(1-coefficient,-defensePoints);}}
    if(!std::isfinite(damage) || damage>1000000000)throw std::runtime_error("Final damage outside supported range");ScriptContext context;context.damageSource=source;context.damageAttack=attack;context.damageRanged=ranged;context.damage=real(float(damage));unitEvent(target,UINT_MAX,52,context);if(alive(target,NativeKind::Unit) && !to->removing && number(to->life)>0){if(dealt)*dealt=std::min(number(to->life),float(damage));unitLife(runtime_.handle("unit",target),real(std::max(0.f,number(to->life)-float(damage))),source);}return true;
}
void ScriptSession::bindDamageNatives() {
    bind("UnitDamageTarget","boolean",{"unit","widget","real","boolean","boolean","attacktype","damagetype","weapontype"},[this](auto& vm,auto a){if(a[1].bits && !alive(a[1].bits,NativeKind::Unit))throw std::runtime_error("Damage to non-unit widgets is not implemented");return vm.boolean(damageUnit(a[0].bits,a[1].bits,number(jass::Real::fromBits(a[2].bits)),a[5].bits,a[6].bits,a[3].bits!=0,a[4].bits!=0));});
    bind("GetEventDamage","real",{},[this](auto& vm,auto){return vm.real(contexts_.empty()?jass::Real{}:contexts_.back().damage);});
    bind("GetEventDamageSource","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().damageSource);});
}
}
